  function rememberSearch(text:string,options:SearchOptions) { const item:SearchHistoryItem={id:crypto.randomUUID(),query:text,editionId:activeEditionId,options,searchedAt:new Date().toISOString()};void queueHistoryChange(items=>recordSearchHistory(items,item)); }
  async function saveCurrentSearch() { if(!manifest||!query.trim())return;const name=window.prompt('Name this saved search (up to 80 characters):');if(name===null)return;const now=new Date().toISOString();const item:SavedSearch={id:crypto.randomUUID(),name,query,editionId:activeEditionId,options:searchOptions,createdAt:now,updatedAt:now};try{await persistSearches(saveSearch(savedSearches,item));notify('Search saved privately on this device.');}catch(error){notify(error instanceof Error?error.message:'Could not save this search.');} }
  function searchPrivateStudy(text:string) { const needle=fold(text.trim());if(!needle){setPrivateSearchResults([]);setPrivateSearchMessage('Enter words to search your private study.');return;}const matches:{kind:string;label:string;text:string;ref?:Reference}[]=[];for(const note of study.notes)if(fold(note.text).includes(needle))matches.push({kind:'Note',label:referenceLabel(note.ref,manifest),text:note.text,ref:note.ref});for(const entry of study.journal)if(fold(entry.text).includes(needle))matches.push({kind:'Question',label:new Date(entry.createdAt).toLocaleDateString(),text:entry.text});for(const ref of study.bookmarks)if(fold(referenceLabel(ref,manifest)).includes(needle))matches.push({kind:'Bookmark',label:referenceLabel(ref,manifest),text:'Saved passage',ref});setPrivateSearchResults(matches.slice(0,100));setPrivateSearchMessage(matches.length?`${matches.length} private matches${matches.length>100?' · showing first 100':''}.`:'No matching private notes, questions, or bookmarks.'); }
